#pragma once
// NEON TITAN preset recipes.
// Each recipe is a hand-designed sound style: fixed values, random ranges and random choices.
// The generator makes a large candidate pool from these; Tools/dedupe.py renders every candidate,
// compares how they actually SOUND, and keeps only the distinct ones (Source/PresetKeep.h).
#include <juce_core/juce_core.h>
#include <vector>
#include <tuple>
#include <map>

struct Recipe
{
    const char* category;
    const char* subtype;
    int pool;                                                        // candidates generated before de-duplication
    std::vector<std::pair<const char*, float>> base;                 // fixed values
    std::vector<std::tuple<const char*, float, float>> ranges;       // random between lo and hi
    std::vector<std::pair<const char*, std::vector<float>>> picks;   // random choice from a list
};

struct GenWords { std::vector<const char*> adj, noun; };

